<?php
namespace App\Jobs\Integrations;
use App\Models\Integration\IntegrationOutboxEvent; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Http;
class DeliverAriyaOutboxEventJob implements ShouldQueue { use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $timeout=60; public bool $afterCommit=true; public function __construct(public int $eventId){} public function tries(): int {return (int)config('ariya_site.max_attempts',10);} public function backoff(): array {return config('ariya_site.backoff',[10,30,120,300,900,3600]);}
 public function handle(): void { $e=IntegrationOutboxEvent::findOrFail($this->eventId); if(in_array($e->status,['delivered','failed'],true)) return; $secret=(string)config('ariya_site.shared_secret',''); $base=rtrim((string)config('ariya_site.base_url',''),'/'); if($base===''||$secret===''){ $e->update(['status'=>'failed','last_error'=>'Ariya site integration is not configured.']); return; } $body=json_encode($e->payload, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); $ts=now()->toIso8601String(); $sig=hash_hmac('sha256',$ts.'.'.$body,$secret); $e->update(['status'=>'processing','attempts'=>$e->attempts+1,'last_attempt_at'=>now()]); $resp=Http::connectTimeout(config('ariya_site.connect_timeout',5))->timeout(config('ariya_site.timeout',15))->withOptions(['verify'=>(bool)config('ariya_site.verify_ssl',true)])->withBody($body,'application/json')->withHeaders(['X-Ariya-Event-Id'=>$e->event_id,'X-Ariya-Timestamp'=>$ts,'X-Ariya-Signature'=>$sig,'X-Ariya-Source'=>'inventory'])->post($base.'/api/integrations/ariya/v1/events'); if($resp->successful()){ $e->update(['status'=>'delivered','delivered_at'=>now(),'last_http_status'=>$resp->status(),'last_error'=>null]); return;} $e->update(['status'=>$resp->status()>=400&&$resp->status()<500&&$resp->status()!=429?'failed':'pending','last_http_status'=>$resp->status(),'last_error'=>mb_substr($resp->body(),0,2000),'available_at'=>now()->addSeconds($this->backoff()[min($e->attempts, count($this->backoff())-1)]??3600)]); if($e->status==='pending') throw new \RuntimeException('Ariya delivery retryable failure '.$resp->status()); }
}
